insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('gaswell', 'intermediate', 'module', 'm01-a-well-is-not-a-station', 1, 'What is the flowing traverse that loadingProfile consumes?', '["A supplied list of stations, each one carrying its own pressure, temperature, compressibility factor and tubing diameter.", "A continuous pressure and temperature gradient that the module builds by integrating upward from the shoe using the gas gravity and the flowing rate.", "A record of the wellhead pressure sampled through the working day.", "A depth log of the liquid standing in the tubing."]'::jsonb, 0, 'Six stations at 1500.0 ft spacing is itself a limit, because nothing between 6000.0 ft and 7500.0 ft exists as far as the profile is concerned.'),
  ('gaswell', 'intermediate', 'module', 'm01-a-well-is-not-a-station', 2, 'The Coleman critical velocity on EBOCHA-5 falls from 7.4662818275 ft/s at the gauge to 6.1224977520 ft/s at the shoe. Why does that fall not make the shoe the easier station?', '["The requirement is compared against a velocity metered at surface, so the fall at depth never reaches the comparison at all.", "The interfacial tension of the produced brine rises with temperature down the hole.", "The rate that velocity corresponds to still rises, from 2671.123287413 to 3222.613396799 Mscf/d, because a standard rate occupies less volume at 1500.0 psia than at 880.0 psia, while the actual velocity falls from 8.6650712734 to 5.8895500931 ft/s.", "Coleman applies no adjustment, so the fall is an artefact of the correlation."]'::jsonb, 2, 'Numerator down and denominator up is why the ratio falls monotonically rather than turning over somewhere in the middle of the string.'),
  ('gaswell', 'intermediate', 'module', 'm01-a-well-is-not-a-station', 3, 'Read down EBOCHA-5 at 3100.0 Mscf/d under Coleman. In what order do the six stations report?', '["The gauge reads loaded and the deeper stations recover, because the pressure supporting the gas climbs steadily with depth on this traverse.", "Four read healthy from the gauge down, then 6000.0 ft and 7500.0 ft read loaded.", "The stations alternate between loaded and healthy, since the ratio turns on the temperature step between one survey point and the next one below it.", "All six stations read loaded at that rate."]'::jsonb, 1, 'The ratios run 1.1605604334, 1.1184659554, 1.0761623743, 1.0340528848, 0.9979085215 and 0.9619521855, in that order.'),
  ('gaswell', 'intermediate', 'module', 'm01-a-well-is-not-a-station', 4, 'Nothing about EBOCHA-5 changes between the rows of its profile. What changed to turn a healthy verdict into a loaded one?', '["The gas rate stepped down between the shallow rows and the deep ones as liquid began to accumulate in the string.", "The tubing tapers below 4500.0 ft, so the flow area behind the actual velocity is not the same on every row of the table.", "The correlation switches to Turner at the stations sitting above the Coleman pressure limit of 1000.0 psia.", "Only the station the equation was evaluated at."]'::jsonb, 3, 'The tubing is 3.548 in throughout and the fluids are one brine at 62.0 dyne/cm and 66.2 lbm/ft3, so both rows are correct evaluations of one equation.'),
  ('gaswell', 'intermediate', 'module', 'm01-a-well-is-not-a-station', 5, 'A survey hands loadingProfile a shoe pressure that is wrong. What does the profile do with it?', '["It returns six confident ratios computed from that number, because a station is an input and the module solves no multiphase flow and has no way to disagree with one.", "It rebuilds the gradient from the gas gravity and the rate, then reports the station as inconsistent.", "It refuses the traverse and returns ok = false.", "It replaces the reading with a hydrostatic estimate."]'::jsonb, 0, 'The shoe ratio of 0.9619521855 is therefore exactly as good as the survey that produced 1500.0 psia, and no better.'),
  ('gaswell', 'intermediate', 'module', 'm01-a-well-is-not-a-station', 6, 'The ratio decrement on EBOCHA-5 holds near 0.0421094894 over the top three intervals and near 0.0359563360 over the bottom two. Where does the step between the two values sit?', '["Between 4500.0 ft and 6000.0 ft, exactly where the ratio passes one, because the crossing changes which term of the balance dominates.", "Between 3000.0 ft and 4500.0 ft, which is above the crossing.", "Between 6000.0 ft and 7500.0 ft, where the second loaded station appears and the liquid falling back begins to add back pressure.", "It sits at the gauge."]'::jsonb, 1, 'The step tracks the pressure steps of the supplied traverse, so there is no kink at the crossing itself.'),
  ('gaswell', 'intermediate', 'module', 'm01-a-well-is-not-a-station', 7, 'On EBOCHA-5 the wellhead ratio is 1.1605604334 and the shoe ratio is 0.9619521855. What is the factor of 1.2064637420 between them?', '["Measurement noise, of the size any two pressure gauges run against each other on one string would show over a working day.", "The Turner adjustment of 1.200000, recovered by the arithmetic.", "The profile itself, which is how much better the gauge reads than the station that decides the well.", "The ratio of the two flow areas."]'::jsonb, 2, 'The tubing size and the fluids are identical at both stations, so nothing about the string can account for the factor.'),
  ('gaswell', 'intermediate', 'module', 'm01-a-well-is-not-a-station', 8, 'The deepest healthy station on EBOCHA-5 is 4500.0 ft and the shallowest loading station is 6000.0 ft. What is the honest statement about where loading starts?', '["It starts somewhere between those two stations.", "It starts at 6000.0 ft, since that is the shallowest depth at which the ratio was found to be below one on this well.", "It starts at 5250.0 ft, which is what a straight line drawn between the two ratios returns for the depth where the fit crosses one.", "It starts at the shoe, because the controlling station is 7500.0 ft and the controlling station is where liquid first falls back."]'::jsonb, 0, 'That bracket places the crossing inside the deepest 40.0000 percent of the string and outside the deepest 20.0000 percent.'),
  ('gaswell', 'intermediate', 'module', 'm01-a-well-is-not-a-station', 9, 'Between 2700.0 and 3000.0 Mscf/d the shallowest loading station on EBOCHA-5 moves from 1500.0 ft to 6000.0 ft. What happened?', '["The two intermediate stations were dropped from the traverse at the higher rate.", "The crossing genuinely jumped when the liquid column broke up and the middle of the string cleaned itself.", "The correlation changed between the two runs, which moved every critical rate by 1.200000.", "A 300.0 Mscf/d step moved the crossing past 3000.0 ft and 4500.0 ft at once, and the profile reports in station-sized steps because stations are all it has."]'::jsonb, 3, 'Reading that column as a smooth migration is the mistake, because a jump in the label is not a jump in the well.'),
  ('gaswell', 'intermediate', 'module', 'm01-a-well-is-not-a-station', 10, 'At 3450.0 Mscf/d nothing on EBOCHA-5 reads loaded and the margin is 7.055969 percent. Is there still a controlling station?', '["No, a controlling station exists only where a station has crossed one, so a healthy well returns no controlling depth at all.", "Yes, 7500.0 ft, because the controlling station is the lowest ratio whether or not anything loads.", "No, the controlling station moves to the gauge once the well is clear, since the margin is then measured at the reading an operator can reach.", "Yes, but it moves up to 6000.0 ft."]'::jsonb, 1, 'Watching that one number on a healthy well is how the approach to the line is seen before it is crossed.'),
  ('gaswell', 'intermediate', 'module', 'm01-a-well-is-not-a-station', 11, 'What does the controlling profile point on EBOCHA-5 carry for a caller who wants to size tubing next?', '["A ready-made recommendation of the tubing size to install, together with the correlation the study should file that recommendation under.", "The margin and the loaded flag, and nothing a sizing could consume.", "pPsia 1500.0, tempR 653.67, z 0.9142643742, idIn 3.548 and depthFt 7500.0, in the units the sizing asks for.", "Only the depth and the ratio."]'::jsonb, 2, 'Nothing makes a caller use it, because the sizing takes a bare pressure, temperature and z from wherever they were found.'),
  ('gaswell', 'intermediate', 'module', 'm01-a-well-is-not-a-station', 12, 'A profile is run with a single wellhead station on EBOCHA-5. What comes back?', '["An error, because the module requires at least two stations before it will name a controlling depth for a well.", "A warning that the survey stopped at surface, attached to the returned controlling station so a caller can see the traverse was short.", "The shoe conditions, filled in by extrapolating the single station down to the tubing shoe depth it was given.", "0.0 ft as the controlling station at a ratio of 1.1605604334, with no complaint."]'::jsonb, 3, 'The controlling station is a minimum over the stations supplied, so it is not a search and not a depth the module found.'),
  ('gaswell', 'intermediate', 'module', 'm01-a-well-is-not-a-station', 13, 'Which two calls does the loading profile refuse outright?', '["An empty traverse, answered with a message that it needs at least one station from the flowing traverse, and a correlation name it does not recognise.", "A traverse whose pressures are inconsistent with the rate, and a rate of zero.", "A station below the Coleman pressure limit, and a negative interfacial tension.", "A single station, and a tubing size outside the candidate list."]'::jsonb, 0, 'An unknown correlation is refused rather than quietly treated as Turner, so the module refuses where it has no answer at all.'),
  ('gaswell', 'intermediate', 'module', 'm01-a-well-is-not-a-station', 14, 'What does a profile run at 3100.0 Mscf/d assert about EBOCHA-5?', '["The rate the well settles at once liquid begins to fall back, which the module finds by stepping the rate down until the shoe ratio returns to one.", "The deliverability of the well against reservoir pressure, taken from the traverse it was handed and the tubing size on every station.", "What happens if the well makes that rate, since the rate was supplied and nothing here computes inflow.", "The volume of liquid falling back each day."]'::jsonb, 2, 'There is no inflow performance anywhere in these modules, so a verdict is a verdict at a rate somebody typed in.'),
  ('gaswell', 'intermediate', 'module', 'm01-a-well-is-not-a-station', 15, 'A report quotes the loading depth on EBOCHA-5 to the nearest foot from a survey cut at 1500.0 ft spacing. What is wrong with it?', '["The report should have quoted the controlling station instead, because the loading depth and the controlling depth are the same number on any normal traverse.", "The profile refuses to interpolate, so the resolution of that answer is the station spacing and no better.", "Nothing, since the ratio falls smoothly and a straight line through it locates the crossing.", "The depth should have been quoted from the shoe upward."]'::jsonb, 1, 'That is a claim about arithmetic dressed as a claim about a well, and the five decrements it would be fitted to came from stations that were supplied rather than solved.'),
  ('gaswell', 'intermediate', 'module', 'm02-reading-a-loaded-well', 1, 'What does marginPct measure on a loading profile?', '["The share of the produced liquid that falls back down the tubing each day.", "The percentage by which the gas rate exceeds the critical rate at the gauge.", "The ratio at the controlling station expressed as a percentage clear of one, so it belongs to a single station rather than to the well as a whole.", "How much of the tubing string sits below the crossing."]'::jsonb, 2, 'It is not a property of the well at all, it is a property of the station the well was read at.'),
  ('gaswell', 'intermediate', 'module', 'm02-reading-a-loaded-well', 2, 'EBOCHA-5 at 3100.0 Mscf/d reports a margin of -3.80478145 percent, while a point check at its wellhead alone would report 16.05604334 percent. What separates the two?', '["The station each was read at, on one well on one day at one gas rate.", "The correlation, since a point check at the gauge is scored under Coleman while a profile scores its controlling station under Turner.", "The gas rate, because the wellhead figure is computed at the rate the operator meters and the deeper figure at the rate reaching the shoe.", "An error in the surveyed pressure at the shoe."]'::jsonb, 0, 'Comparing the two as though they were two wells is the second half of the mistake, because they are one well.'),
  ('gaswell', 'intermediate', 'module', 'm02-reading-a-loaded-well', 3, 'Across a rate sweep from 2400.0 to 3200.0 Mscf/d the loaded flag on EBOCHA-5 never changes. What does the margin do over the same span?', '["It holds near -25.526282 percent, because the flag and the margin come from the same comparison and cannot disagree with one another.", "It crosses zero at 3000.0 Mscf/d while the flag stays true.", "It is not reported while the flag reads true.", "It walks from -25.526282 to -0.701710 percent, which is what says the well is nearly back."]'::jsonb, 3, 'One of the two is a trend and the other is a word, which is why the margin is the more useful of them.'),
  ('gaswell', 'intermediate', 'module', 'm02-reading-a-loaded-well', 4, 'An engineer reads a margin of -3.80478145 percent as a shortfall in gas. What is the error?', '["The margin is quoted against the critical rate of 3222.613396799 Mscf/d rather than against the 3100.0 Mscf/d the well is making.", "The margin is a distance from one, not a fraction of any rate.", "The margin is a percentage of the liquid the well produces each day, so it converts into barrels rather than into a gas rate at all.", "The margin is measured at the gauge, so the shortfall it describes is real but has been quoted at the wrong station of the well."]'::jsonb, 1, 'The rate that would close it is not the margin times anything, because the requirement at the controlling station is a separate number.'),
  ('gaswell', 'intermediate', 'module', 'm02-reading-a-loaded-well', 5, 'At 2400.0 Mscf/d every station on EBOCHA-5 reads loaded and at 3200.0 Mscf/d only 7500.0 ft does. What does the margin say about that difference?', '["It says the string is loading over four times as much of its length, since the margin scales with the number of stations that have crossed one.", "It reports the difference as a percentage of the string below the crossing.", "Nothing, because it is one number from one station and the difference lives in the station list.", "It flags the second case as mild loading."]'::jsonb, 2, 'Both cases are a single negative number, and the shallowest loading station is what separates them.'),
  ('gaswell', 'intermediate', 'module', 'm02-reading-a-loaded-well', 6, 'Why can a margin of -3.80478145 percent not be filed on its own?', '["The same six stations scored under Turner give the same controlling depth of 7500.0 ft and a margin of -19.83731788 percent, and the figure alone cannot say which of the two it is.", "Margins are comparable only between wells that share a tubing size.", "The margin is reported to eight decimals, which is more precision than a survey supports.", "A margin has no meaning until the well has been shut in and built up."]'::jsonb, 0, 'One of those two numbers describes a well worth watching and the other a well worth a workover, and they are the same well on the same day.'),
  ('gaswell', 'intermediate', 'module', 'm02-reading-a-loaded-well', 7, 'A published sweep reads 0.9911148002 at 1600.0 Mscf/d, 0.9997870547 at 1614.0 Mscf/d and 1.1150041502 at 1800.0 Mscf/d. How does the flag read across those three?', '["True, false, then false, since a ratio within a thousandth of one is treated as clear and the flag fires only on a definite crossing.", "True, true, then false, because the test is a strict comparison against one.", "True, true, then true, because the flag stays set once a station has crossed one until the well has been unloaded by an intervention.", "False at all three rates."]'::jsonb, 1, 'A well a fraction under the line and a well far under it are given the same word, which is what the flag will not grade.'),
  ('gaswell', 'intermediate', 'module', 'm02-reading-a-loaded-well', 8, 'Four stations on EBOCHA-5 read false and two read true at 3100.0 Mscf/d. What does the well report?', '["loaded = false, since the majority of the surveyed stations still carry the gas.", "loaded = false, because the gauge reads clear and the gauge is the well-level reading.", "A graded verdict, weighted by the fraction of the string below the crossing.", "loaded = true, because the well-level flag is an OR across the stations and liquid falling back over the bottom of the string is a loaded well."]'::jsonb, 3, 'That is the correct answer whatever the top of the well reads, and it is why an OR is the right rule here.'),
  ('gaswell', 'intermediate', 'module', 'm02-reading-a-loaded-well', 9, 'What does the loaded flag refuse to do?', '["Grade how far a station sits below one.", "Fire at a station whose ratio sits within a thousandth of one, which it treats as a tie.", "Report at well level, since it is only ever set on the individual stations of the traverse.", "Take account of the correlation, which it records separately on every row it returns."]'::jsonb, 0, 'It will not distinguish a station at 0.9979085215 from one at 0.744737, and it will not weight a crossing by how much of the string lies below it.'),
  ('gaswell', 'intermediate', 'module', 'm02-reading-a-loaded-well', 10, 'A well comes back with loaded = false. Why is that not the same as no liquid in the tubing?', '["The flag is set only at the stations supplied, so a traverse cut at 1500.0 ft spacing can step over a loading interval lying between two healthy ones.", "The flag is raised only once the shallowest loading station has reached the gauge.", "The balance models one droplet at its terminal velocity and knows nothing about film flowing on the tubing wall.", "A false flag holds only until the next survey is run."]'::jsonb, 2, 'Film flow is the other way a gas well carries liquid, and it is outside the droplet picture entirely.'),
  ('gaswell', 'intermediate', 'module', 'm02-reading-a-loaded-well', 11, 'A report carries the loaded flag and nothing else. Which three numbers has it dropped?', '["The critical velocity, the actual velocity and the flow area, none of which survive into the well-level object a profile returns to its caller.", "The margin, the controlling depth and the shallowest loading station.", "The correlation, the adjustment and the droplet constant, which are recorded on each row and are what a downstream reader needs to reproduce a verdict.", "The gas rate, the liquid rate and the water cut."]'::jsonb, 1, 'All three come back in the same returned object, so dropping them is a choice made by whoever wrote the report.'),
  ('gaswell', 'intermediate', 'module', 'm02-reading-a-loaded-well', 12, 'At 3000.0 Mscf/d the EBOCHA-5 station at 4500.0 ft reads 1.000696 and the shallowest loading station is reported as 6000.0 ft. What should a reader make of that label?', '["It rests on 4500.0 ft clearing one by under a thousandth, which is well inside the noise any field pressure would carry, so the label is decided by a margin nobody could measure.", "It is firm, because the ratio is computed to six decimals from the station the survey supplied.", "It is wrong, since a station that close to one should have been flagged loaded by the module.", "It shows the crossing has already reached 4500.0 ft and the report is one station behind."]'::jsonb, 0, 'One step of rate from 2700.0 to 3000.0 Mscf/d moved that label past three stations, and the profile has no way to express how close a call it was.'),
  ('gaswell', 'intermediate', 'module', 'm02-reading-a-loaded-well', 13, 'What fraction of the EBOCHA-5 string is loading at 3100.0 Mscf/d under Coleman?', '["Exactly two fifths, taken from the deepest healthy station at 4500.0 ft on a 7500.0 ft string.", "Rather more than half, since the crossing sits above the midpoint of the tubing on this well.", "None of it, because the well-level margin is negative only at the controlling station itself.", "Between a fifth and two fifths of it."]'::jsonb, 3, 'The bracket is 1500.0 ft wide because the survey was cut at 1500.0 ft spacing, so a narrower answer needs a finer survey.'),
  ('gaswell', 'intermediate', 'module', 'm02-reading-a-loaded-well', 14, 'Two surveillance readings report the same loaded flag and the same 6000.0 ft crossing, at margins of -6.907853 and -3.804781 percent. What has a report carrying only the flag and the crossing thrown away?', '["Nothing that matters, since a crossing depth is the deeper instrument and a margin below zero is a margin below zero however far below it happens to sit.", "The correlation the reading was taken under, because a margin is the one field in the profile that carries the twenty percent adjustment forward with it.", "The distance to the verdict, which is the only one of the three that says whether the well is close to recovering.", "The station count, since a profile reporting one crossing depth has already discarded the stations above and below it at which the margin was measured."]'::jsonb, 2, 'A flag and a crossing both saturate and a margin does not: it moved from -6.907853 to -3.804781 percent while neither of the other two fields moved at all.'),
  ('gaswell', 'intermediate', 'module', 'm02-reading-a-loaded-well', 15, 'Under Turner the same six EBOCHA-5 stations give a margin of -19.83731788 percent. What does that do to a verdict quoted downstream?', '["It changes the controlling station from 7500.0 ft to 4500.0 ft, because Turner flags the shallower stations that Coleman leaves clear on this well.", "It carries a factor of 1.200000 unless the correlation travels with it, which is the difference between watching a well and working it over.", "It leaves the verdict alone, since both correlations agree the well is loaded.", "It makes the margin a Turner-only quantity."]'::jsonb, 1, 'The critical rate at the shoe moves by 644.522679360 Mscf/d between the two, on one well on one day.'),
  ('gaswell', 'intermediate', 'module', 'm03-sizing-the-tubing', 1, 'The Coleman critical velocity at the EBOCHA-5 controlling station is 6.1224977520 ft/s. What does it read for the 1.610 in candidate?', '["28.6020782357 ft/s, because the smaller flow area raises the velocity a string has to produce before a droplet can be carried.", "4.6716355635 ft/s, since the requirement falls with diameter and that is the whole reason a velocity string unloads a well.", "It is not reported for rejected candidates.", "6.1224977520 ft/s, the same as for every other candidate on the list."]'::jsonb, 3, 'Critical velocity is built from the gas density of 4.2000760651 lbm/ft3 and the brine at 62.0 dyne/cm and 66.2 lbm/ft3, so changing the string does not move it.'),
  ('gaswell', 'intermediate', 'module', 'm03-sizing-the-tubing', 2, 'What does changing the tubing size actually change in a loading calculation?', '["The gas density at the station, which falls as the string is narrowed.", "The flow area, so the same 3100.0 Mscf/d travels faster past a droplet that still needs 6.1224977520 ft/s to be carried.", "The interfacial tension of the produced brine against the wall.", "The pressure at the shoe, which a smaller string lowers."]'::jsonb, 1, 'The critical rate follows the area in the same direction, 4010.445008120 Mscf/d on 3.958 in against 663.579159341 Mscf/d on 1.610 in.'),
  ('gaswell', 'intermediate', 'module', 'm03-sizing-the-tubing', 3, 'Of the nine EBOCHA-5 candidates under Coleman, which ones unload the well at 3100.0 Mscf/d?', '["3.476, 3.068, 2.441, 2.041 and 1.610 in.", "Every candidate below the current string, together with 3.548 in itself, which clears at a ratio of 0.9619521855 at the controlling station.", "3.958, 3.826 and 3.740 in.", "Only 1.610 in."]'::jsonb, 0, 'The line between the group that clears and the group that does not is where the workover argument sits, and it is a line rather than a preference.'),
  ('gaswell', 'intermediate', 'module', 'm03-sizing-the-tubing', 4, 'EBOCHA-5 runs 3.548 in and the Coleman pick at its controlling station is 3.476 in. What does that say about the well?', '["It is far oversized, since five of the nine candidates on the list would unload it at this rate.", "It is correctly sized, because 3.548 in appears on the candidate list the sizing was given.", "It is one size wrong.", "It cannot be unloaded by a velocity string at all, which is why the pick sits so close to the current size."]'::jsonb, 2, 'The current string is the smallest candidate that still fails, which is what puts the well immediately on the wrong side of the line.'),
  ('gaswell', 'intermediate', 'module', 'm03-sizing-the-tubing', 5, 'What does installing a velocity string on EBOCHA-5 not do?', '["Raise the actual velocity at the controlling station.", "Add gas, lower the shoe pressure or change the brine, since the critical velocity of 6.1224977520 ft/s belongs to the station and the fluids.", "Reduce the flow area the gas has to fill.", "Move the ratio at every candidate station."]'::jsonb, 1, 'It moves the same supplied rate through less area, which is the entire mechanism and the limit of it.'),
  ('gaswell', 'intermediate', 'module', 'm03-sizing-the-tubing', 6, 'What does a smaller string cost in these modules?', '["Nothing, because there is no pressure drop calculation anywhere in them.", "A friction penalty worked out from the roughness and the wall thickness of the candidate, which each row returns beside its ratio.", "A share of the deliverability, taken off the supplied gas rate before the actual velocity in the new string is computed.", "One tubing size of margin."]'::jsonb, 0, 'That is why the objective always lands on the boundary: the constraint is hard and nothing is priced on the other side of it.'),
  ('gaswell', 'intermediate', 'module', 'm03-sizing-the-tubing', 7, 'The same nine candidates at the same EBOCHA-5 controlling station give which two picks?', '["3.740 in under Coleman and 3.476 in under Turner, which is the pair a study reports when the conditions are taken from the gauge at 880.0 psia.", "3.548 in under both, since the current string is on the list.", "3.068 in under both correlations.", "3.476 in at 1.0022156322 under Coleman and 3.068 in at 1.0720838440 under Turner."]'::jsonb, 3, 'One correlation choice, made from a wellhead pressure, moves the boundary one candidate down an ordered list of nine.'),
  ('gaswell', 'intermediate', 'module', 'm03-sizing-the-tubing', 8, 'What happens to the Coleman pick of 3.476 in when the list is scored under Turner instead?', '["It keeps its ratio and gains a warning on the row.", "It becomes the pick under both, at a ratio of 0.8351796935.", "It loses 0.1670359387 of ratio, which is 16.666667 percent of it, and drops from being the answer to being a reject.", "It moves up the list above 3.548 in."]'::jsonb, 2, '3.068 in makes the opposite trip, from comfortably surplus at 1.2865006128 to the only candidate that just clears at 1.0720838440.'),
  ('gaswell', 'intermediate', 'module', 'm03-sizing-the-tubing', 9, 'What is largestUnloaded, stated as an objective?', '["The diameter whose ratio sits furthest above one, which is the safest of the candidates the list contains.", "The largest inside diameter whose ratio still clears one.", "The diameter closest to the string already in the hole that still unloads the well at the supplied rate.", "The diameter that balances the workover cost against the deliverability the new string returns."]'::jsonb, 1, 'The function walks the list largest first and stops at the first row that clears, so the rows below the pick were seen, scored and rejected for being smaller.'),
  ('gaswell', 'intermediate', 'module', 'm03-sizing-the-tubing', 10, 'Why is the pick ratio of 1.0022156322 not a design margin?', '["It is what is left over when the biggest string that fits is taken.", "It is a margin the function was configured with, and a study can raise it by setting a higher threshold on the candidate list.", "It is a measured quantity, since the ratio comes from the pressure and temperature the survey recorded at the controlling station.", "It is quoted to too few digits."]'::jsonb, 0, 'The function had no opinion about how much headroom anybody wanted, and it stated the leftover to ten digits all the same.'),
  ('gaswell', 'intermediate', 'module', 'm03-sizing-the-tubing', 11, 'What do the two candidates either side of the Coleman pick tell an engineer?', '["Nothing, since the function scores only the pick and returns the other candidates as diameters with no ratio attached to either of them.", "That the pick would change if the gas rate moved by 0.1670359387.", "3.068 in at 1.2865006128 is what buying margin costs in diameter, and 3.548 in at 0.9619521855 is what doing nothing costs.", "That the candidate list was cut too coarsely."]'::jsonb, 2, 'Weighting candidates by cost, availability or workover risk is a decision a person makes, and the sizing applies none of them.'),
  ('gaswell', 'intermediate', 'module', 'm03-sizing-the-tubing', 12, 'Run the EBOCHA-5 candidate list at 40.0 Mscf/d. What comes back?', '["1.610 in, the smallest candidate, as the closest the list can come.", "An error, because the rate is below the range the module accepts.", "The current 3.548 in string, unchanged.", "largestUnloaded is null and the best ratio anywhere on the list is 0.0502326405, so there is no least bad candidate and no clamp to the smallest diameter."]'::jsonb, 3, 'It also refuses to invent a candidate below 1.610 in, so the list it was given is the list it answers from.'),
  ('gaswell', 'intermediate', 'module', 'm03-sizing-the-tubing', 13, 'A study sizes EBOCHA-5 from its gauge conditions of 880.0 psia rather than from the shoe. What does the function do?', '["It accepts them and returns 3.740 in, which is larger than the 3.548 in already in the hole, so the study reports that no workover is needed.", "It refuses the call, because the sizing checks the pressure it is handed against the controlling station of the profile that produced the traverse.", "It accepts them and returns 3.476 in, since the pick is fixed by the correlation and the rate rather than by the pressure and temperature handed in.", "It returns the same pick as at the shoe."]'::jsonb, 0, 'The function is not wrong. It answers the question it was asked, at the station it was given, while the well loads over the bottom 40.0000 percent of its tubing.'),
  ('gaswell', 'intermediate', 'module', 'm03-sizing-the-tubing', 14, 'What is the station worth in tubing on this well?', '["Nothing, since both stations sit on the same string and the same candidate list is scored either way.", "0.264 in under Coleman and 0.408 in under Turner.", "One full candidate under Coleman and two under Turner, counted along the ordered list of nine diameters.", "It cannot be priced, because the returned object records no depth against either of the two answers."]'::jsonb, 1, 'The wellhead list under Turner picks 3.476 in at 1.0076140183 and the controlling list picks 3.068 in, so the same substitution runs one size along.'),
  ('gaswell', 'intermediate', 'module', 'm03-sizing-the-tubing', 15, 'Each returned row carries idIn, ok, correlation, adjustment, densities, velocities, the ratio and the loaded flag. Which field would have caught a sizing run at the wrong station?', '["The constant field, which records the droplet constant the row was built with and therefore the pressure and the temperature that were used to produce it at that station.", "The correlation field, which names the station the recommendation was taken from.", "None of them, because the depth is recorded nowhere and the pressure reaches the answer only through the density and the velocity it produced.", "The ok field, which is false on rows scored away from the controlling station."]'::jsonb, 2, 'The correlation is recorded on every single row while the station is recorded on none, and that asymmetry is what turns a stated limit into a quiet failure.'),
  ('gaswell', 'intermediate', 'module', 'm04-the-plunger', 1, 'The engine represents a plunger installation as which two pieces of arithmetic?', '["A transient momentum solve for the plunger, integrated from the moment the well is opened until the slug reaches the surface.", "A slug tracking model that follows the liquid falling back past the rising plunger and takes it off the volume delivered.", "A gas slippage calculation across the plunger seal, which sets how much of the casing gas reaches the tubing above it.", "A static force balance and a set of typed times."]'::jsonb, 3, 'There is no velocity in the balance and no fallback of the slug during the rise, so the 10.93333333 min rise on OGUTA-2 is a distance divided by a speed.'),
  ('gaswell', 'intermediate', 'module', 'm04-the-plunger', 2, 'A trip on OGUTA-2 lifts 0.9261160790 bbl. What is in that figure?', '["The slug and nothing else, its 160.0 ft length across a 4.6797800340 in2 cross-section converted at 5.614583 ft3/bbl.", "The slug together with the liquid the plunger passes through near the bottom, which is why the fall is split at 172.0 ft/min.", "The liquid the well accumulates during the 40.0 min shut-in, which is what a trip is timed to carry away.", "The slug less whatever falls back past the plunger on the way up."]'::jsonb, 0, 'Length and volume are exact inverses here, and on the published case a 200.0 ft slug gives 1.1576450988 bbl and that volume gives back 200.0000000000 ft.'),
  ('gaswell', 'intermediate', 'module', 'm04-the-plunger', 3, 'Which numbers behind the 89.90356589 min OGUTA-2 cycle were never computed?', '["The rise and the fall durations, which are read off a published plunger velocity chart rather than solved from the depth.", "The 750.0 ft/min rise speed, both fall speeds of 1000.0 and 172.0 ft/min, the 30.0 min afterflow and the 40.0 min shut-in.", "None of them, since the whole cycle is solved from the depth, the slug and the casing pressure the screen was handed.", "The afterflow alone."]'::jsonb, 1, 'They are operating inputs with stated typical bands, so the 14.83375148 bbl/d that follows rests on times somebody filled into a form.'),
  ('gaswell', 'intermediate', 'module', 'm04-the-plunger', 4, 'Which of the five lift pressure terms is the largest on the published case, and what follows from that?', '["The 88.3320000000 psi slug hydrostatic, so shortening the slug is the first lever to reach for whenever a requirement has to come down.", "The 16.2440440692 psi gas column, which is why the pressure its density is evaluated at decides more than any other choice in the balance.", "The 120.0000000000 psi line pressure, so the cheapest change to a lift requirement is often not downhole at all.", "The 1.2821115429 psi plunger weight, since a lighter plunger costs nothing to change."]'::jsonb, 2, 'The five terms sum to 225.8581556122 psia and the largest of them is a surface number rather than anything in the hole.'),
  ('gaswell', 'intermediate', 'module', 'm04-the-plunger', 5, 'Friction on the published plunger case reads 0.0000000000 psi. What does that reading mean?', '["A frictionless plunger, which is the modelling assumption the static balance rests on and the reason no velocity appears anywhere in it.", "A friction term that fell under the resolution of the balance, because the other four terms are three orders of magnitude larger than it is.", "An absent measurement, since nothing here estimates friction and the term is only ever what somebody handed in.", "A term the engine solved and found to vanish at this slug length and this plunger weight."]'::jsonb, 2, 'It enters linearly, so 40.0 psi of friction takes the published requirement to 265.8581556122 psia, which is 40.0000000000 psi more and nothing else.'),
  ('gaswell', 'intermediate', 'module', 'm04-the-plunger', 6, 'The gas column term needs a gas density. At which pressure does the engine evaluate it?', '["At the line pressure.", "At the pressure the balance is solving for, which on OGUTA-2 is the 248.1897322873 psia sitting at the bottom of that same column of gas.", "At the average of the line pressure and the pressure under the slug, which on the published case is the mean of 120.0 psia and 225.8581556122 psia.", "At the casing pressure, since the gas standing above the slug is the gas the casing supplied."]'::jsonb, 0, 'On OGUTA-2 that is 145.0 psia, a gas density of 0.5015053107 lbm/ft3 and 0.003482675768 psi per foot, giving 28.0007131786 psi over the tubing above the slug.'),
  ('gaswell', 'intermediate', 'module', 'm04-the-plunger', 7, 'An engineer recomputes the gas column at the pressure under the slug, disagrees with the engine and files it as a defect. What is the actual position?', '["The engine is in error, because the gas at the bottom of that column sits near the pressure the balance is solving for rather than at the line.", "Both readings are defensible and the returned object records no pressure for the term, so the only way to know which one you hold is to reproduce it.", "The question is closed, because the module header states which pressure the density is evaluated at and the engineer did not read it.", "It cannot matter, since the term is small beside the line pressure."]'::jsonb, 1, 'The independent oracle carries the term the same way and the two gas column terms agree to 3.4680e-5 psi on the published case, so this is a convention left unstated.'),
  ('gaswell', 'intermediate', 'module', 'm04-the-plunger', 8, 'Against the oracle, the liquid a cycle carries agrees to the last digit while the gas a cycle spends does not. Why?', '["The liquid volume is published as a golden while the gas per cycle is only ever the shipped engine re-run on its own published inputs.", "The gas figure carries the rounded gradient constant of 0.433 through the requirement it expands down to, and the liquid figure carries none of it.", "The two implementations disagree about how many cubic feet make a barrel, so the gas parted and the liquid was corrected to 5.614583 ft3/bbl.", "The liquid is geometry and the gas is a thermodynamic path."]'::jsonb, 3, 'Both return 1.1576450988 bbl, while the gas per cycle stands at 5452.924357073 scf against 5453.635111991 scf, a difference of -0.710754919 scf.'),
  ('gaswell', 'intermediate', 'module', 'm04-the-plunger', 9, 'Walk the OGUTA-2 casing pressure down. Which of the required lift pressure and the required gas-liquid ratio moves?', '["Both, since the casing is what holds the slug up and the balance solves for the pressure the casing has to supply.", "Only the lift pressure, because less casing means less support under the plunger and a larger requirement standing above it.", "Only the ratio, because the gas per cycle is an expansion from the casing down to the requirement and no lift term is a casing pressure.", "Neither, since both of them belong to the slug."]'::jsonb, 2, 'The lift stays at 248.1897322873 psia whatever the casing reads, while the requirement of 9561.17363265 scf/bbl at 720.0 psia does not.'),
  ('gaswell', 'intermediate', 'module', 'm04-the-plunger', 10, 'The 400.0 scf per bbl per 1000 ft screening rule against what the balance actually asks. Which way does the rule err?', '["Toward flattery on both of these cases, asking 2400.00000000 scf/bbl on the published depth where the balance asks 4710.35929989 scf/bbl.", "Toward caution, because a rule built on depth alone has to cover the deepest well anybody might apply it to and therefore overstates the gas.", "Neither way, because the rule is scaled to the depth of the well in front of it and the balance is scaled to that same depth.", "Toward flattery on shallow wells and toward caution on deep ones."]'::jsonb, 0, 'The balance is 1.96264971 times as demanding on the published case and 2.91499196 times on OGUTA-2, so a well that clears the rule comfortably can still be short.'),
  ('gaswell', 'intermediate', 'module', 'm04-the-plunger', 11, 'Give OGUTA-2 a 1500.0 min shut-in. What does the screen say about it?', '["It refuses the case, since a cycle longer than a day is not an installation the static balance is able to price at all.", "It raises slowCycle, because at 1549.90356589 min the well makes 0.92909006 trips a day.", "It raises nothing new, because the timing inputs carry stated typical bands and a value outside them is taken without comment.", "It raises a warning that the liquid carried per day has fallen under what the well makes, which is the check a shut-in most directly moves."]'::jsonb, 1, 'That is the only timing check there is and it fires on trips rather than on barrels, so a cycle too slow to happen daily is reported and one too small to matter is not.'),
  ('gaswell', 'intermediate', 'module', 'm04-the-plunger', 12, 'OGUTA-2 comes back with ok = true. What has been asserted?', '["That the plunger can be driven on this well, which is what the flag is for and the reason it is reported ahead of the other two.", "That the casing clears the required lift pressure of 248.1897322873 psia, which on this well it does by a margin of 471.8102677127 psi.", "That a depth, a diameter, a slug shorter than its tubing, a plunger weight and a temperature were all present and usable.", "That the cycle carries enough liquid to keep the well unloaded."]'::jsonb, 2, 'It would come back true on any well with a self-consistent set of inputs, and on OGUTA-2 the plunger cannot be driven at all.'),
  ('gaswell', 'intermediate', 'module', 'm04-the-plunger', 13, 'feasible reads false on OGUTA-2. Which flag failed, and what does the other one say?', '["The pressure flag failed, since 720.0 psia of casing cannot reach the 248.1897322873 psia the lift requires behind a 160.0 ft slug.", "Both failed, which is why feasible is the two of them joined rather than a separate calculation carrying anything of its own.", "Neither failed, and ruleOfThumbAgrees turned feasible false.", "The gas flag failed, and the pressure has 471.8102677127 psi to spare."]'::jsonb, 3, 'A pressure failure and a gas failure lead to different conversations, and a cycle needing 9561.17363265 scf/bbl against 5900.0 scf/bbl is the one to have here.'),
  ('gaswell', 'intermediate', 'module', 'm04-the-plunger', 14, 'The insufficientGas warning ends with the words at this slug size. Why do those four words matter?', '["They record the slug the screen solved for, which is the longest one a casing of 720.0 psia can lift on this particular well.", "The requirement is per barrel and the barrels come from the slug, so the verdict belongs to a slug length rather than to the well.", "They warn that a slug longer than the tubing it sits in was refused earlier in the same call.", "They mark the requirement as provisional until a measured slug length is supplied."]'::jsonb, 1, 'Which way to move the slug is a separate question the screen does not answer, because slug length sets the barrels a trip carries and sets the lift pressure with them.'),
  ('gaswell', 'intermediate', 'module', 'm04-the-plunger', 15, 'liquidPerDayBbl on OGUTA-2 reads 14.83375148 bbl/d and the well makes 194.91525424 bbl/d. Where does that comparison enter the verdict?', '["Nowhere at all, since feasible is pressureOk and glrOk and nothing else, and no warning carries the comparison either.", "Into the insufficientGas warning, which prices the 180.08150275 bbl/d shortfall against the cycle that produced it and names the slug it belongs to.", "Into slowCycle, which fires exactly when a cycle turns out too small to carry the liquid the well is making.", "Into feasible, as the third of its three inputs."]'::jsonb, 0, 'The well makes 13.13998380 times what the cycle carries, and the screen computes both sides of that and never sets one against the other.'),
  ('gaswell', 'intermediate', 'module', 'm05-choosing-a-remedy', 1, 'A velocity string is scored at one station while more gas is felt at every station. What does the EBOCHA-5 rate sweep show for the second of those?', '["The shoe clears first at 3200.0 Mscf/d, where the margin reads -0.701710 percent and the stations above it are already healthy.", "Nothing on the column loads at 3450.0 Mscf/d, where the margin first turns positive at 7.055969 percent.", "The stations clear from the bottom up, so the deepest one turns healthy first and the crossing walks upward as the rate rises.", "Only the shallow stations respond, because the actual velocity is a surface rate divided by an area."]'::jsonb, 1, 'Rate lifts every ratio in the column at once, and on this well nothing clears below 3450.0 Mscf/d against a well making 3100.0 Mscf/d.'),
  ('gaswell', 'intermediate', 'module', 'm05-choosing-a-remedy', 2, 'The EBOCHA-5 sizing was scored at 3100.0 Mscf/d. What does the current 3.548 in string read once the well has fallen to 2400.0 Mscf/d?', '["Every station loading, at a margin of -25.526282 percent.", "The same margin of -3.804781 percent, because the ratio is a comparison at a station and both of its sides fall together with the rate.", "A margin of -16.217068 percent with the shallowest loading station at 1500.0 ft, which is where a declining well first shows the change.", "A shallower controlling station than the shoe."]'::jsonb, 0, 'A string sized to the rate you have is sized to a rate that falls, and the shallowest loading station has already climbed from 6000.0 ft to 0.0 ft by then.'),
  ('gaswell', 'intermediate', 'module', 'm05-choosing-a-remedy', 3, 'sizeTubingForRate scored nine EBOCHA-5 candidates at 7500.0 ft, 1500.0 psia, 653.67 degR and z 0.9142643742. What was held still while the diameter changed?', '["Nothing, since each station pressure is rebuilt from the candidate diameter.", "The gas rate alone, with the station pressure recomputed for the new bore.", "The traverse, so the friction a narrower string adds and the pressures it would shift are outside the answer.", "The correlation, which is the only input a candidate row does not carry."]'::jsonb, 2, 'Every candidate is scored at one set of conditions, so a 2.441 in candidate is priced at a 1500.0 psia the 3.548 in string produced.'),
  ('gaswell', 'intermediate', 'module', 'm05-choosing-a-remedy', 4, 'What does a plunger spend on OGUTA-2, beyond the equipment?', '["Only flowing time, because the gas driving the plunger is returned to the line on every trip and the cycle is a closed exchange.", "Only gas, since 40.0 min of shut-in and 30.0 min of afterflow inside an 89.90356589 min cycle are time the well would have lost anyway.", "Neither, because the screen reports both figures and the verdict then weighs them against the liquid the cycle brought up.", "Gas, at 141.82807355 Mscf/d, and flowing time."]'::jsonb, 3, 'The cycle runs 89.90356589 min with 40.0 min shut in, and that gas is spent on every trip whether or not the trip was worth making.'),
  ('gaswell', 'intermediate', 'module', 'm05-choosing-a-remedy', 5, 'The cost of a workover doubles overnight. Which fields in what sizeTubingForRate returns move?', '["The largestUnloaded field, which weighs a bigger bore''s cheaper run against the ratio a smaller one buys before it names a pick.", "The ok field on each row, once a candidate stops paying for itself.", "None, because it returns rows, largestUnloaded and ok, and not one of them is money or time.", "The ratio, since the objective is scored against a threshold a study sets."]'::jsonb, 2, 'There is nothing to compare a 3.476 in workover against 16.01716223 plunger trips a day with, because neither answer is expressed in anything the other one is.'),
  ('gaswell', 'intermediate', 'module', 'm05-choosing-a-remedy', 6, 'Nothing on EBOCHA-5 clears every station below 3450.0 Mscf/d and the well makes 3100.0 Mscf/d. What do these modules say about closing that gap?', '["That compression would close it, which the modules price by holding the traverse still and rerunning the profile at the lower wellhead pressure.", "Nothing at all, since there is no inflow performance anywhere in them and the rate is an input.", "That the reservoir cannot supply it, a rate that high being refused.", "That a smaller string reaches the same place, at a ratio of 1.0022156322."]'::jsonb, 1, 'The gas rate is supplied, so every verdict is a verdict at a rate somebody handed in rather than a forecast of what the well would give.'),
  ('gaswell', 'intermediate', 'module', 'm05-choosing-a-remedy', 7, 'Condensate at 20.0 dyne/cm and 45.0 lbm/ft3 needs 1102.641685283 Mscf/d where water at 60.0 dyne/cm and 67.0 lbm/ft3 needs 1614.343188395 Mscf/d at one published station. What does that pair license a treatment study to claim?', '["That changing the produced liquid would move the bar, and nothing about what any treatment produces.", "That a surfactant reaching a tension of 20.0 dyne/cm buys the difference between the two rates, since the module carries both fluids as correlations against pressure.", "Nothing, because interfacial tension and liquid density enter the terminal velocity rather than the critical rate that carries the verdict.", "That the treated well would read 1102.641685283 Mscf/d once a soap stick programme is running on it."]'::jsonb, 0, 'Both properties are inputs and neither is a function of anything these modules know, so the engine will score a fluid change and will never propose one.'),
  ('gaswell', 'intermediate', 'module', 'm05-choosing-a-remedy', 8, 'A candidate at a ratio of 1.0022156322 and one at 1.2865006128 both come back with unloads = true. What does the pair of them cost?', '["The same, because both clear at the same station on the same rate and the constraint they clear is the identical strict comparison against one.", "The larger of the two ratios costs more gas, since a higher ratio is bought by moving the same volume faster and that velocity has to come from somewhere.", "Neither costs anything the sizing did not already report on its row, which carries the ratio, the critical rate and the correlation it was scored under.", "One is a workover two sizes down that the well has to keep flowing through for years."]'::jsonb, 3, 'The engine reports both to ten digits and neither to a currency, so pricing a remedy in ratio points is pricing it in the one unit nobody buys anything with.'),
  ('gaswell', 'intermediate', 'module', 'm05-choosing-a-remedy', 9, 'The Coleman pick on EBOCHA-5 clears in its third decimal at 1.0022156322. What kind of margin is that?', '["A design margin the sizing was configured with.", "A measured margin, since the ratio is built from the pressure, the temperature and the z the survey recorded at the controlling station.", "A leftover, and one that reads 0.8351796935 if the other correlation is used on the same diameter.", "A conservative margin, because the correlation the wellhead selected is the one that demands the higher critical rate of the two."]'::jsonb, 2, 'It is what is left over when the biggest string that fits is taken, and 3.068 in at 1.2865006128 is the candidate that survives a bad assumption.'),
  ('gaswell', 'intermediate', 'module', 'm05-choosing-a-remedy', 10, 'A plunger carries 0.9261160790 bbl a trip at 16.01716223 trips a day. What does that buy that a velocity string does not?', '["Liquid delivered on a timer rather than by a velocity, so it does not care what any ratio in the column reads.", "A better ratio at every station, since removing the liquid speeds the gas.", "A lower critical velocity, because the slug is not carried in the gas.", "A larger flow area, which is what 2.441 in tubing buys against the 3.548 in the well runs."]'::jsonb, 0, 'That is 14.83375148 bbl/d up the hole whatever the gas is doing, and the casing has 471.8102677127 psi more than the 248.1897322873 psia the lift needs.'),
  ('gaswell', 'intermediate', 'module', 'm05-choosing-a-remedy', 11, 'The EBOCHA-5 gauge shows a margin of 16.05604334 percent on the day a remedy study is written. What is the bottom third of that string doing?', '["The stations below the midpoint read the same ratio, because the correlation chosen at 880.0 psia is applied to all six of them.", "The stations at 6000.0 ft and 7500.0 ft are losing liquid, at 0.9979085215 and 0.9619521855.", "The station at 4500.0 ft has already crossed, at 1.0340528848.", "Nothing, since a healthy gauge on a flowing well is a healthy column."]'::jsonb, 1, 'The reading argues for no remedy at all while the bottom third of the tubing drops liquid, which is why every remedy has to be argued at the controlling station.'),
  ('gaswell', 'intermediate', 'module', 'm05-choosing-a-remedy', 12, 'A design proposes cutting the OGUTA-2 shut-in to raise the trips a day. What does the screen do with that proposal?', '["It solves for the shut-in that carries the well''s liquid make, which is the one timing figure the balance is able to close on its own.", "It refuses the case, since a shut-in below the typical band it publishes is outside the operating envelope the timings are declared over.", "It moves the required gas-liquid ratio of 9561.17363265 scf/bbl down with the cycle, because a shorter cycle expands less gas per trip.", "It recomputes the cycle on the times you handed it and optimises nothing."]'::jsonb, 3, 'The rise of 750.0 ft/min, both falls, the afterflow and the shut-in are operating inputs with stated typical bands, not computed and not optimised.'),
  ('gaswell', 'intermediate', 'module', 'm05-choosing-a-remedy', 13, '3.068 in at 1.2865006128 and 2.441 in at 2.0322875149 both clear on EBOCHA-5 and the sizing returns 3.476 in. What has been decided for you?', '["That the ratio nearest one is the efficient answer, which is the optimisation the function performs across the candidates that clear.", "That a workover should be as small as the list allows, so the smallest clearing candidate is held back as the conservative reserve.", "That the biggest bore that works is the one you want.", "Nothing, because the function returns every scored row and leaves the choice among the ones that clear entirely open to the caller."]'::jsonb, 2, 'It is a reasonable preference, since a bigger bore is cheaper to run and easier to intervene through, and the returned object does not say a preference was applied.'),
  ('gaswell', 'intermediate', 'module', 'm05-choosing-a-remedy', 14, 'A study files its header as Coleman on EBOCHA-5. What did the engine do to settle that?', '["It scored both names across the traverse and reported the one whose verdict the six stations agreed on most often.", "It returned a name and a sentence for the one pressure it was handed, and switched nothing.", "It fixed the name for the study, which is why every sizing row carries coleman and an adjustment of 1.0000.", "It compared 880.0 psia against the limit twice."]'::jsonb, 1, 'recommendCorrelation takes one pressure and returns guidance rather than a decision, and it cannot see which station that pressure came from.'),
  ('gaswell', 'intermediate', 'module', 'm05-choosing-a-remedy', 15, 'largestUnloaded = 3.476 in is handed to a decision maker as the recommendation. What has been left out of that sentence?', '["That it is the biggest listed bore clearing one, at one station, at one rate, under one correlation.", "That the diameter is an inside diameter and not a nominal size.", "That the pick was scored at 3100.0 Mscf/d and at no other rate.", "Nothing, because the field is the engine''s answer to the question the study asked it."]'::jsonb, 0, 'Every one of those four qualifiers was a choice somebody made, and the recommendation is the part you add.'),
  ('gaswell', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'The reading names the controlling station before it sizes anything. What does taking the steps the other way round cost on EBOCHA-5?', '["The candidate list returns 3.740 in from the gauge conditions instead of the 3.476 in the shoe conditions pick, which is 0.264 in of tubing bought at the top of the well.", "A slower answer only, since the same nine candidates are scored either way.", "The correlation, which is chosen from the station the sizing was handed.", "The ratio on every row, which the sizing recomputes once a controlling depth is named."]'::jsonb, 0, 'The controlling profile point already carries pPsia, tempR, z and idIn so it can be handed straight in, and nothing makes a caller do it.'),
  ('gaswell', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'The reading asks for the crossing to be reported as a pair rather than as a depth. Which pair does EBOCHA-5 give?', '["7500.0 ft at 0.9619521855 and 6000.0 ft at 0.9979085215, the two stations that read loaded, which is the interval the liquid falls back over.", "0.0 ft at 1.1605604334 and 7500.0 ft at 0.9619521855, the two ends of the column, since the crossing has to lie between whatever the traverse covers.", "4500.0 ft at 1.0340528848 and 6000.0 ft at 0.9979085215.", "6000.0 ft alone, since the shallowest loading station is where loading starts."]'::jsonb, 2, 'The traverse was cut at 1500.0 ft spacing, so the deepest healthy station and the shallowest loading one are the whole of what the profile knows.'),
  ('gaswell', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'Step five reads pressureOk, glrOk and feasible, and then reads liquidPerDayBbl on its own. Why separately?', '["Because it is computed from the timing block and the other three come from the balance, so the two groups are returned on different objects.", "Because no verdict uses it, so it has to be compared to the well by hand.", "Because it moves with the shut-in while the flags do not, and reading them together would attach a timing choice to a pressure result.", "Because it is the third input to feasible."]'::jsonb, 1, 'OGUTA-2 carries 14.83375148 bbl/d against a well making 194.91525424 bbl/d, and feasible is pressureOk and glrOk and nothing else.'),
  ('gaswell', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'Step two asks for the correlation once and writes the station down beside the name. What makes the station worth recording?', '["The name is recorded on every sizing row and the station on none, so the station has to be reconciled against the rows before a study can be filed.", "The function refuses a pressure it cannot place, so the station is what turns a bare refusal into an answer a reader can act on.", "The limit of 1000.0 psia is stated at the wellhead, so a pressure from any other station has to be corrected back to gauge conditions first.", "One well answers coleman at 880.0 psia and turner at 1500.0 psia."]'::jsonb, 3, 'recommendCorrelation takes one pressure and returns guidance rather than a decision, and the answer carried through the study is whichever station was handed in.'),
  ('gaswell', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'One check is that the five plunger terms must sum. What makes friction the easiest of the five to test by hand?', '["It is the only term the balance solves for, so a hand calculation reproduces it from the plunger weight and the slug length together.", "It is zero on the published case, so any total above it is an entry error.", "It is linear and additive, so 40.0 psi of it takes the published 225.8581556122 psia to 265.8581556122 psia.", "It scales with the slug, so doubling the slug doubles it and the sum can be checked at two slug lengths."]'::jsonb, 2, 'Friction is an input, measured rather than modelled, and 40.0 psi added to the case moves the requirement by 40.0000000000 psi and nothing else.'),
  ('gaswell', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'The failures to expect include taking the 400.0 scf per bbl per 1000 ft rule as the requirement. What does the balance ask on the published plunger case?', '["4710.35929989 scf/bbl against the rule''s 2400.00000000 scf/bbl, so the physics is 1.96264971 times as demanding.", "The same figure, since the rule is scaled to the depth of the well and so is the gas column inside the balance.", "Less than the rule, which is why the rule is carried as a screening test.", "A figure the screen refuses to compute whenever the rule and the balance disagree by more than a factor of two."]'::jsonb, 0, 'The rule is carried for comparison only and never used to decide feasibility, and which side of it a well sits on is reported through ruleOfThumbAgrees.'),
  ('gaswell', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'Module one established what a traverse is. What did EBOCHA-5''s own traverse then show?', '["Gas density falling with depth as the gas expands into the wider bore below the tubing hanger, which is what lifts the deeper ratios.", "Gas density climbing from 2.8547437868 to 4.2000760651 lbm/ft3 with the ratio falling at every step.", "A ratio that falls to a minimum near the midpoint and recovers at the shoe, where the pressure and the temperature both rise together.", "A critical rate that holds still down the column."]'::jsonb, 1, 'The crossing sits between 4500.0 ft and 6000.0 ft, which is inside the deepest 40.0000 percent of the string.'),
  ('gaswell', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'Module two established what a verdict is. Which station carries it?', '["The shallowest one that reads loaded, since that is where the liquid first fails to be carried and everything below it is already lost.", "The one the traverse names as the gauge, because that is the station an operator can go and read against the report on the same day.", "Whichever station the correlation was chosen at, because a verdict and a correlation have to be quoted at one depth to be consistent.", "The worst one, which is neither the average nor the first."]'::jsonb, 3, 'EBOCHA-5 reads loaded = true at -3.80478145 percent from its 7500.0 ft shoe while its wellhead reads loaded = false at 1.1605604334 and 16.05604334 percent.'),
  ('gaswell', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'Module three established what a velocity string is. What happened when the same search was run at the gauge on EBOCHA-5?', '["It returned 3.740 in, which is larger than the 3.548 in already hanging in the well, so the study read as no workover needed.", "It returned no candidate at all, since the gauge conditions put the whole list below one.", "It returned 3.476 in, because the pick follows the rate and the correlation rather than the station.", "It refused the conditions, having been given a pressure from a station the profile did not name as controlling."]'::jsonb, 0, 'The well is loading over the bottom 40.0000 percent of its tubing while that answer is returned, and no field on any row records the depth it was scored at.'),
  ('gaswell', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'Module four established what a plunger screen is. On which of its two tests did OGUTA-2 fail?', '["The pressure test, since a casing of 720.0 psia cannot reach the 248.1897322873 psia the lift requires behind that slug.", "Both of them, which is why feasible is reported as a joined verdict rather than as two separate flags a reader has to combine.", "The gas test, at 9561.17363265 scf/bbl needed against 5900.0 scf/bbl made.", "Neither, feasible being false on the rule of thumb."]'::jsonb, 2, 'The casing has 248.1897322873 psia to beat and 720.0 psia to beat it with, so the failure is on gas and the two failures lead to different conversations.'),
  ('gaswell', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'Module five established that four remedies exist and that the engine scores all of them. What will it not do with them?', '["Score a fluid change, interfacial tension and liquid density being inputs it declines to take from a treatment programme.", "Choose one, since it returns ratios and requirements to ten digits and not one cost, duration or date.", "Rank the candidates that clear, which is why largestUnloaded comes back as one line with the rejected rows left unscored.", "Report a rejected candidate."]'::jsonb, 1, 'It scores a fluid change and never proposes one, and 3.068 in at 1.2865006128 is returned scored and rejected beside the pick.'),
  ('gaswell', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'Walk the OGUTA-2 casing from 900.0 psia down to 90.0 psia. What does the Expert tier find the required gas-liquid ratio doing?', '["Rising as the casing falls, which is the physics: less pressure behind the plunger asks more gas of every barrel it lifts.", "Holding at 9561.17363265 scf/bbl, since the requirement is fixed by the slug and the depth rather than by the casing.", "Falling until the casing reaches the lift requirement and then refusing, which is the guard the expansion carries at its crossing.", "Falling 70.545832 percent, all of it in the flattering direction."]'::jsonb, 3, 'It ends the walk at 3339.72840586 scf/bbl on a well that cannot move the plunger at all, so glrOk turns true as the well dies.'),
  ('gaswell', 'intermediate', 'module', 'm06-the-professional-reading', 13, 'The slug gradient is carried as 0.433 psi/ft per unit specific gravity against an exact 0.4335275040010. What kind of error is that?', '["A fixed 0.1216771707 percent of whatever slug it sits on, worth 0.1076108162 psi on the published case.", "A rounding that cancels against the gas column term.", "An error that grows with the casing pressure, since the constant enters the expansion the gas requirement is averaged over.", "A tolerance the gate sets, rather than a constant the engine ships."]'::jsonb, 0, 'A cost in psi divides straight back to the slug that produced it, which is why the same percentage lands on every slug the constant is used on.'),
  ('gaswell', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'Which Expert subject could change a workover recommendation without a single measurement on the well changing?', '["The gradient constant, because 0.1216771707 percent of a slug moves a lift requirement and a lift requirement decides a tubing size.", "The liquid capacity the screen never checks, since 14.83375148 bbl/d against 194.91525424 bbl/d would rule the plunger out and leave the workover.", "The correlation, since 3.476 in reads 1.0022156322 under Coleman and 0.8351796935 under Turner.", "The clamp at zero, which returns a length rather than refusing."]'::jsonb, 2, 'Turner is Coleman times 1.200000000000 at every station, so the pick moves from 3.476 in to 3.068 in on a name chosen from one pressure.'),
  ('gaswell', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'What stays in force when the Expert tier opens?', '["The correlation seam replaces the controlling station, since the choice is made at the wellhead and the shoe verdict follows from it.", "The traverse is still handed in, the plunger balance is still static and its timings are still inputs.", "The profile now solves multiphase flow, which is what lets the expert findings be priced in pressure rather than in ratio.", "The plunger timings become results of the casing sweep."]'::jsonb, 1, 'Nothing the Expert tier finds gives these modules a capability they refused, and the deepest failing station still carries the verdict.'),
  ('gaswell', 'intermediate', 'final', null, 1, 'EBOCHA-5 reads 880.0 psia at its gauge and 1500.0 psia at its shoe, a pressure ratio of 1.70454545. What does that ratio account for in the loading profile?', '["The fall in the actual velocity, which follows from the string tapering below the midpoint so the flow area shrinks with depth.", "The Turner adjustment of 1.200000, which the profile recovers by comparing the gauge against the shoe and then applies at every station of the traverse.", "The rise in gas density from 2.8547437868 to 4.2000760651 lbm/ft3, which is what pushes the critical rate up from 2671.123287413 to 3222.613396799 Mscf/d.", "Nothing in the profile, since pressure enters only through the correlation the wellhead selects."]'::jsonb, 2, 'Density is the pressure times a molecular weight over z R T, so a pressure ratio at nearly constant z carries most of the way into the density and from there into every critical rate in the column.'),
  ('gaswell', 'intermediate', 'final', null, 2, 'At 2400.0 Mscf/d every station on EBOCHA-5 reads loaded, the shallowest at 0.0 ft, and the margin is -25.526282 percent. What does the gauge tell you on that well?', '["Nothing at all, because a point check carries meaning only once a profile has been run and the controlling station named somewhere below it.", "The same thing the shoe does, because at that rate the gauge has crossed one as well.", "That the well is clear, since the wellhead ratio of 1.1605604334 is computed at the rate the operator meters rather than at the rate reaching the shoe.", "That the crossing has reached 1500.0 ft."]'::jsonb, 1, 'A gauge is a station like any other and it happens to be the easiest one, so it fails last: at 3100.0 Mscf/d it reads 1.1605604334 and at 2400.0 Mscf/d it reads 0.898498.'),
  ('gaswell', 'intermediate', 'final', null, 3, 'The EBOCHA-5 critical rate climbs by 100.530141186, 108.952764374, 117.306240181, 108.584738855 and 116.116224791 Mscf/d across its five intervals. What would a fall in that sequence tell you?', '["That a station is out of order or a pressure is wrong, since on a normal traverse the critical rate rises with depth.", "That liquid is falling back, which adds hydrostatic head at the deeper stations and lowers the rate they demand from the gas beneath them.", "That the correlation switched to Turner inside the traverse, multiplying the deeper critical rates by 1.200000.", "Nothing, because the increments are not required to be monotonic."]'::jsonb, 0, 'It is a capstone check for that reason, and the increments are uneven even when they are right: the step from 117.306240181 to 108.584738855 Mscf/d is the traverse''s own pressure spacing.'),
  ('gaswell', 'intermediate', 'final', null, 4, 'The EBOCHA-5 controlling profile point carries pPsia 1500.0, tempR 653.67, z 0.9142643742 and idIn 3.548, and sizeTubingForRate takes a bare pressure, temperature and z. What follows from that pairing?', '["The sizing reads the controlling point whenever a profile has been run first, so the two functions are already joined and a caller cannot separate them by accident.", "The sizing validates the pressure it is handed against the traverse that produced it and refuses conditions taken from a station that is not the controlling one.", "The controlling point cannot be used, because its z came from Sutton and DAK rather than from the survey.", "Handing the sizing the right station is available, free and entirely voluntary."]'::jsonb, 3, 'Nothing makes a caller do it, and the wellhead run comes back as 3.740 in with no field on any row recording where it stood.'),
  ('gaswell', 'intermediate', 'final', null, 5, 'Scored under Turner rather than Coleman, EBOCHA-5''s six stations part company with the Coleman verdict at four depths. Which four?', '["6000.0 and 7500.0 ft, because the two correlations separate where the pressure has climbed past the Coleman limit of 1000.0 psia and Turner''s data begins.", "0.0, 1500.0, 3000.0 and 4500.0 ft.", "All six, since every critical rate on the column moves by a factor of 1.200000 when the correlation name is changed.", "0.0, 3000.0, 4500.0, 7500.0 ft."]'::jsonb, 1, 'They agree at 6000.0 ft and 7500.0 ft where the well loads under both, so the disagreement sits at the top four stations, the ones an operator uses to call the well healthy.'),
  ('gaswell', 'intermediate', 'final', null, 6, 'At the EBOCHA-5 controlling station the Coleman critical rate is 3222.613396799 Mscf/d and the Turner critical rate is 3867.136076159 Mscf/d. What is the 644.522679360 Mscf/d between them?', '["What the correlation name is worth at the one station that decides the well.", "The gas the well would have to add to clear its shoe under Coleman, which is why the rate sweep first turns the margin positive at 3450.0 Mscf/d.", "The spread of critical rate between the gauge and the shoe, which runs from 2671.123287413 to 3222.613396799 Mscf/d on this same well.", "A tolerance to be carried through the study and quoted at the end of it."]'::jsonb, 0, 'It is larger than the whole gauge-to-shoe spread of critical rate under Coleman, on a well flowing 3100.0 Mscf/d.'),
  ('gaswell', 'intermediate', 'final', null, 7, 'Asked at each of the six EBOCHA-5 stations rather than once at the gauge, what does recommendCorrelation return?', '["coleman at every station, because the function is handed the wellhead pressure by the profile and has no other pressure available to it.", "turner at every station, since each station inherits the correlation the study was run under and the study was run under a single name.", "coleman at 880.0 psia and 978.0 psia, then turner at 1090.0, 1218.0, 1350.0 and 1500.0 psia.", "coleman down to 4500.0 ft, then turner below it."]'::jsonb, 2, 'The comparison is strict against 1000.0 psia, so the wellhead choice is coleman while the controlling station would have chosen turner.'),
  ('gaswell', 'intermediate', 'final', null, 8, 'Hand loadingProfile the name coleman and every station is scored under coleman. What will it not do?', '["Refuse a name it does not recognise, which it accepts and then treats as turner on the grounds that turner is the more conservative of the two.", "Vary the correlation with depth, or run both and report the pair.", "Accept a traverse of one station, which it rejects as too short to name a controlling depth on.", "Record the adjustment of 1.0000 on the rows it returns."]'::jsonb, 1, 'It refuses an unknown correlation outright, answering that turner or coleman are the two it takes, but it has no argument for a per-station list.'),
  ('gaswell', 'intermediate', 'final', null, 9, 'sizeTubingForRate walks 3.958, 3.826, 3.740, 3.548, 3.476, 3.068, 2.441, 2.041 and 1.610 in in that order. Why does it stop at 3.476 in under Coleman?', '["Its ratio of 1.0022156322 sits closest to one, which is the smallest change in condition that still clears the threshold on this candidate list.", "It sits immediately below the current 3.548 in string, so the search begins from the tubing already in the hole and steps down one size at a time.", "It is where a smaller string stops paying, because below it the friction the sizing charges outweighs the ratio a narrower bore buys.", "It is the first row on that ordering whose ratio reaches one."]'::jsonb, 3, 'Largest first and stop at the first that clears is the whole objective, so 3.068 in at 1.2865006128 was seen, scored and rejected for being smaller.'),
  ('gaswell', 'intermediate', 'final', null, 10, 'Across the EBOCHA-5 candidate list the actual velocity runs from 4.7325778044 ft/s on 3.958 in to 28.6020782357 ft/s on 1.610 in. What does the critical velocity do over the same list?', '["It sits at 6.1224977520 ft/s on every row, because it belongs to the station and the fluids rather than to the string.", "It rises with the actual velocity, since a narrower bore resolves the balance in a faster stream.", "It falls, which is the second half of what a velocity string buys and the reason the ratio moves twice.", "It is reported only on the row that is picked."]'::jsonb, 0, 'The tubing enters through the flow area alone, from 0.0854434880 down to 0.0141377124 ft2, which is why nine rows share one velocity.'),
  ('gaswell', 'intermediate', 'final', null, 11, '3.476 in reads 1.0022156322 under Coleman and 0.8351796935 under Turner. What kind of statement is it to call that string adequate on EBOCHA-5?', '["A measurement, since both ratios were computed at the controlling station from the pressure, temperature and z the survey recorded there.", "A statement about the steel, which is the same under either reading and therefore independent of the correlation the study filed.", "One contingent on a comparison against 1000.0 psia made at the top of the well.", "A rounding artefact, since the Coleman reading clears one only in its third decimal and would not survive being quoted to fewer digits."]'::jsonb, 2, 'It loses 0.1670359387 of ratio, 16.666667 percent of it, in a crossing that changes nothing whatever about the well.'),
  ('gaswell', 'intermediate', 'final', null, 12, 'What is not priced anywhere when the sizing recommends 3.476 in over the 3.548 in already in the hole?', '["The critical velocity, which the sizing charges to each candidate through the adjustment on its own row.", "The friction a narrower string adds and the deliverability it costs, because there is no pressure drop calculation in these modules.", "The flow area, which enters only through the actual velocity and is never converted into a rate.", "The correlation, which is recorded on none of the rows."]'::jsonb, 1, 'The constraint is hard and nothing is priced on the other side of it, so the answer always lands on the boundary at 1.0022156322.'),
  ('gaswell', 'intermediate', 'final', null, 13, 'The OGUTA-2 cycle runs 10.93333333 min rising, 8.97023256 min falling, 30.0 min of afterflow and 40.0 min shut in, for 16.01716223 trips a day. How many of the five timing inputs behind that were computed?', '["Two, the rise and the fall, which the balance solves from the 8.20 lb plunger and the gas above it before the cycle is assembled.", "Four, everything except the shut-in, which is the one figure an operator sets at the controller and the engine therefore leaves alone.", "All five, from the depth, the slug and the casing pressure.", "None of them."]'::jsonb, 3, 'The rise of 750.0 ft/min and the falls of 1000.0 and 172.0 ft/min are defaults with typical bands, so 14.83375148 bbl/d rests on a form somebody filled in.'),
  ('gaswell', 'intermediate', 'final', null, 14, 'The OGUTA-2 gas column term of 28.0007131786 psi is built on a gas density of 0.5015053107 lbm/ft3. At which pressure was that density evaluated?', '["At the line pressure of 145.0 psia, although the gas at the bottom of the column sits near the 248.1897322873 psia the balance is solving for.", "At the casing pressure of 720.0 psia, which drives the gas into the column and is the only pressure the term could use.", "At the average of the line pressure and the required lift pressure, which is the convention the independent oracle carries for the same term.", "At the pressure under the slug, which the balance solves for first."]'::jsonb, 0, 'It is a convention rather than an error and the oracle carries the term the same way, agreeing on the published case to 3.4680e-5 psi, but the returned object records no pressure for it.'),
  ('gaswell', 'intermediate', 'final', null, 15, 'Set the OGUTA-2 depth to zero and the screen returns two errors together rather than one. Why?', '["The screen validates every input twice, at the door and again inside the balance, and reports both passes so a caller can see which stage rejected the case.", "The second error is the plunger weight, which cannot be resolved against zero depth.", "A 160.0 ft slug is longer than a well of no length, so the consequence is reported beside the cause.", "One of the two is fatal and the other is a warning."]'::jsonb, 2, 'The messages are that the plunger has to travel a depth and that the slug is longer than the tubing it sits in, and the engine resolves neither into the other.'),
  ('gaswell', 'intermediate', 'final', null, 16, 'OGUTA-2 returns ok = true, pressureOk = true, glrOk = false and feasible = false. What does ok say?', '["That the pressure balance closed, which is the first of the two tests feasible is built from and the reason feasible can still come back false.", "That the inputs were present and usable.", "That the plunger can be run, subject to the warnings the screen attached to this case.", "That the well clears the 400.0 scf per bbl per 1000 ft screening rule."]'::jsonb, 1, 'It is true on a well where the plunger cannot be driven and would be true on any self-consistent input set, so the pair that carries a verdict is feasible and the flag beneath it that failed.'),
  ('gaswell', 'intermediate', 'final', null, 17, 'OGUTA-2 fails on gas while holding 471.8102677127 psi of pressure to spare. What does that margin say about where to look next?', '["Add a trip a day by cutting the shut-in, which is the only lever that moves the gas requirement per barrel without touching the slug at all.", "Nothing, because feasible is false and a false verdict is not a starting point for a design change on a well.", "Raise the line pressure of 145.0 psia, which is the largest single term in the balance.", "Work on the ratio rather than on the casing pressure."]'::jsonb, 3, 'A pressure failure and a gas failure lead to different conversations, and the requirement of 9561.17363265 scf/bbl is per barrel at a 160.0 ft slug, which sets both halves of the ratio at once.'),
  ('gaswell', 'intermediate', 'final', null, 18, 'screenPlungerLift returns fourteen fields and sizeTubingForRate returns three. Which quantity does neither of them work out?', '["The rate the well will make, since there is no inflow performance anywhere in these modules.", "The critical velocity, which the sizing carries on every row it returns beside the ratio and the correlation it was scored under.", "The gas a cycle spends, which the screen reports as 8854.756635640 scf a trip and 141.82807355 Mscf/d across a day on OGUTA-2.", "The flow area."]'::jsonb, 0, 'Both answer at a rate somebody supplied, 3100.0 Mscf/d on the sizing and 1150.0 Mscf/d on the screen, so neither verdict is a forecast.'),
  ('gaswell', 'intermediate', 'final', null, 19, 'Drop the OGUTA-2 afterflow entirely and cut the shut-in to zero. What happens to the gap between what the cycle carries and what the well makes?', '["It closes, because 67.00342849 bbl/d at 72.34884482 trips a day is more than the well makes at 5900.0 scf/bbl.", "It widens, since a shorter cycle lifts a shorter slug.", "It narrows to a factor of 2.90903404 and does not close.", "It cannot be worked out, because the screen carries no field for the well''s own liquid make."]'::jsonb, 2, 'Timing is not the lever here, and a zero shut-in with no afterflow is not an installation anybody would run.'),
  ('gaswell', 'intermediate', 'final', null, 20, 'On the published plunger case a 200.0 ft slug gives 1.1576450988 bbl and that volume gives back 200.0000000000 ft. What does that check establish?', '["That the gas half closes, which is the other route through the same balance and the half that carries the thermodynamic path.", "That the liquid half of a cycle is geometry, which is why the oracle reproduces it exactly.", "That the liquid gravity of 1.020 was applied at the right end of the conversion, since a gravity error shows up as a length that does not come back.", "That the 4.6797800340 in2 cross-section matches the 2.441 in diameter behind it."]'::jsonb, 1, 'The gas half does not agree exactly: 5452.924357073 scf against the oracle''s 5453.635111991 scf, a difference of -0.710754919 scf.'),
  ('gaswell', 'intermediate', 'final', null, 21, 'The 400.0 scf per bbl per 1000 ft rule gives 2400.00000000 scf/bbl on the published case where the balance asks 4710.35929989 scf/bbl. What does the engine do with ruleOfThumbAgrees?', '["Uses it to decide feasibility when the well''s own gas-liquid ratio has not been supplied, which is the case the flag exists to cover.", "Raises a warning whenever the two figures disagree, on the grounds that a factor of 1.96264971 between a heuristic and a balance is worth putting in front of a reader.", "Adjusts the computed requirement toward the rule at shallow depths.", "Reports it and consumes it nowhere."]'::jsonb, 3, 'It reports which side of the two figures a well sits on, and the physics asked 1.96264971 times the heuristic there and 2.91499196 times it on OGUTA-2.'),
  ('gaswell', 'intermediate', 'final', null, 22, 'Four remedies exist for a loading well and each moves one of three quantities in the ratio. What are the three?', '["A gas gravity, a liquid gravity and a temperature, which is the set a station density is built from and therefore the set every remedy has to work through.", "A wellhead pressure, a shoe pressure and a depth.", "A critical velocity at the station, a flow area and a rate.", "A critical rate, a margin and a controlling station."]'::jsonb, 2, 'A smaller string cuts the area, more gas raises the actual velocity, lower station pressure moves the density both ways at once, and a plunger leaves the argument altogether.'),
  ('gaswell', 'intermediate', 'final', null, 23, 'A foamer changes the interfacial tension and the liquid density of the produced liquid. What can these modules do with that?', '["Score the change if you hand both numbers in, and never propose one.", "Compute the tension a given surfactant loading produces at the station temperature, then score the treated case against the untreated one.", "Nothing, because tension and density enter only the terminal velocity and the verdict is not built on the terminal velocity.", "Refuse it, since a fluid change sits outside the droplet balance."]'::jsonb, 0, 'Both are inputs and neither is a function of anything the engine knows, which is why water at 60.0 dyne/cm and 67.0 lbm/ft3 gives 1614.343188395 Mscf/d and condensate at 20.0 dyne/cm and 45.0 lbm/ft3 gives 1102.641685283 Mscf/d at one published station.'),
  ('gaswell', 'intermediate', 'final', null, 24, 'The EBOCHA-5 pick was made at 3100.0 Mscf/d. What does the rate sweep on the current string say about that pick?', '["That the pick holds at every rate, because the critical velocity of 6.1224977520 ft/s belongs to the station, not the rate.", "That at 2400.0 Mscf/d every station loads at a margin of -25.526282 percent, so a string sized to today''s rate is sized to a rate that falls.", "That the pick moves up a size as the rate falls, since a lower actual velocity is easier to reach inside a larger bore.", "Nothing, since the sweep was run on the 3.548 in string rather than on the candidates."]'::jsonb, 1, 'The candidate ratios are computed at one rate, and the shallowest loading station on the current string has climbed to 1500.0 ft by 2700.0 Mscf/d.'),
  ('gaswell', 'intermediate', 'final', null, 25, 'A remedy would change the pressures in the string. What does loadingProfile do about that?', '["Rebuilds the traverse from the new tubing size, the gas gravity of 0.620 and the rate, which is what lets a sizing and a profile be chained together.", "Flags the old traverse as stale once the diameter on any station differs from the one that produced those pressures.", "Interpolates between the old stations.", "Nothing, until you hand it a new traverse."]'::jsonb, 3, 'The traverse is passed in as a list of stations with their own pressure, temperature, z and diameter, and the module solves no multiphase flow and invents no gradient.'),
  ('gaswell', 'intermediate', 'final', null, 26, 'Take what sizeTubingForRate returns and what screenPlungerLift returns together. What is absent from both?', '["The correlation and the adjustment, neither of which is recorded on a returned row, so a reader has to supply both from the call that produced them.", "The ratio and the margin, which are computed inside each function and reduced to a flag before the object is handed back.", "Any cost, duration, rig time, deferred production or date.", "The gas rate, which enters both and neither returns."]'::jsonb, 2, 'There is nothing to compare a 3.476 in workover against 16.01716223 plunger trips a day with, because neither answer is expressed in anything the other one is.'),
  ('gaswell', 'intermediate', 'final', null, 27, 'largestUnloaded is the largest inside diameter whose ratio clears one. What is that?', '["A preference for the biggest bore that works, made once by an engine author and stated nowhere in the return.", "A physical constraint, since a bore any larger than 3.476 in cannot carry 3100.0 Mscf/d past a droplet at that station under either correlation.", "A cost optimum, weighing the cheaper run of a bigger bore against the ratio a smaller one buys.", "A refusal, because the function will not rank the candidates that clear."]'::jsonb, 0, 'It is a reasonable preference, since a bigger bore is cheaper to run, and 3.068 in at 1.2865006128 and 2.441 in at 2.0322875149 clear as well.'),
  ('gaswell', 'intermediate', 'final', null, 28, 'The professional reading asks for the correlation once and writes the station down beside the name. Why the station?', '["Because the profile records the station on every row it returns and the two records have to be reconciled before a study can be filed.", "Because one well produced coleman at 880.0 psia and turner at 1500.0 psia, so the answer carried through a study is whichever station was handed in.", "Because recommendCorrelation refuses a pressure with no station label and answers that no pressure could be read.", "Because the correlation has to be asked again at every station."]'::jsonb, 1, 'The function takes one pressure and cannot see where it came from, so the station is the part only the caller knows.'),
  ('gaswell', 'intermediate', 'final', null, 29, 'One capstone check is that Turner over Coleman reads 1.200000000000 at every station. What has gone wrong if it does not?', '["The adjustment was applied to the velocity rather than to the rate, which breaks the factor because a rate is not linear in velocity once the area enters it.", "The droplet constant of 1.5935346111 was rebuilt with a different drag coefficient.", "The traverse carried a diameter change between the two runs.", "The two runs were not the same station."]'::jsonb, 3, 'The adjustment is 1.200000 against 1.000000 and it survives the conversion to rate, so the factor holds on every published row and every EBOCHA-5 station.'),
  ('gaswell', 'intermediate', 'final', null, 30, 'The Professional tier used a correlation chosen at the wellhead and never audited it. Which other two choices did it use the same way?', '["The traverse, which the tier solved from the gas gravity of 0.620 and the rate before scoring any station on it.", "The droplet constant and the drag coefficient of 0.44, which the tier rebuilt from the critical Weber number before using either of them.", "The station the sizing was handed, and the flags the plunger screen does not compute.", "The rate, which the tier took from an inflow relation."]'::jsonb, 2, 'Carrying the station with every number is what makes those findings visible rather than surprising, because a ratio, a critical rate and a tubing size all belong to one depth and none of them says which.'),
  ('gaswell', 'intermediate', 'final', null, 31, 'A study sizes EBOCHA-5 at the gauge and files 3.740 in against a current string of 3.548 in. What does the report say, and what is the well doing?', '["It says no workover is needed, while the well loads over the bottom 40.0000 percent of its tubing.", "It says a workover to a larger bore would unload the well, which is the right direction on a well whose shoe reads 0.9619521855.", "It says the string is one size too large, since 3.740 in sits above 3.548 in on the candidate list and the pick is always the size to install.", "It refuses, because 3.740 in is not the string in the hole."]'::jsonb, 0, 'The same list at the controlling station picks 3.476 in, so the station is worth 0.264 in of tubing and the sign of the recommendation with it.'),
  ('gaswell', 'intermediate', 'final', null, 32, '3.548 in appears on the EBOCHA-5 candidate list at a ratio of 0.9619521855. What does the sizing know about it?', '["That it is the current string, which it records in the row''s ok field so a caller can see whether the pick is a change or a confirmation.", "That it is one of nine diameters it was asked to score.", "That it is the largest candidate that fails, which it reports beside largestUnloaded as the size a workover would be measured against.", "That it is the diameter the traverse was built on, since every station carries idIn 3.548."]'::jsonb, 1, 'Whether 3.476 in against a current 3.548 in is a workover is a comparison the caller makes, and that same ratio is the well''s own loading verdict at the shoe.'),
  ('gaswell', 'intermediate', 'final', null, 33, 'Which is the largest of the five terms in the OGUTA-2 required lift pressure of 248.1897322873 psia?', '["The slug hydrostatic at 73.4368000000 psi, which is the load the plunger exists to lift and the term every design change is aimed at.", "The gas column at 28.0007131786 psi, carried over the tubing standing above the slug.", "The line pressure, at 145.0000000000 psi.", "The casing pressure at 720.0 psia, which drives the whole balance."]'::jsonb, 2, 'The largest term is a surface number, so the cheapest change to a lift requirement is often not downhole at all, and the plunger weight of 1.7522191087 psi is the smallest of the five.'),
  ('gaswell', 'intermediate', 'final', null, 34, 'loadingProfile is given a traverse and screenPlungerLift is given a casing pressure, a line pressure and an average temperature. What do those two calls share?', '["The profile builds its traverse from the rate and the gas gravity of 0.620 while the screen solves its casing from the balance, so both make their own conditions.", "Both derive z from Sutton and Dranchuk and Abou-Kassem at the conditions they were given, which is the one route into a density either of them has.", "Both refuse a station they cannot place, which is why an empty traverse and a depth of zero come back as errors rather than as numbers.", "Every pressure in both was handed in."]'::jsonb, 3, 'The traverse is a list of stations with their own pressure, temperature, z and diameter, and the plunger balance is static on the pressures it was handed.'),
  ('gaswell', 'intermediate', 'final', null, 35, 'A point check at 0.0 ft on EBOCHA-5 reads a ratio of 1.1605604334, loaded = false and a margin of 16.05604334 percent. What does that reading argue for?', '["No remedy at all, while the bottom two stations are losing liquid.", "A velocity string, since the margin a sizing consumes is the one quoted at the gauge and 16.05604334 percent is not enough to leave a well sitting on.", "A plunger, because a point check cannot see the shoe and the safe reading is always the mechanical one.", "More gas, since the ratio is above one but below the 1.2064637420 the profile carries."]'::jsonb, 0, 'Every remedy has to be argued at the controlling station, where the same well on the same day reads 0.9619521855 and -3.80478145 percent.'),
  ('gaswell', 'intermediate', 'final', null, 36, 'The profile returns loaded and the plunger screen returns feasible. What does each refuse to grade?', '["loaded refuses to report at well level and feasible refuses to report before the timing has been supplied, so both need a second call before they mean anything.", "loaded refuses to say how far below one a station sits, and feasible refuses to weigh a pressure failure against a gas failure.", "loaded refuses a station outside the traverse and feasible refuses a slug longer than its tubing.", "Neither refuses anything, since the margin and the warnings carry the grading."]'::jsonb, 1, 'A station at 0.9979085215 and one at 0.744737 get one word, and OGUTA-2 reads feasible = false with 471.8102677127 psi of pressure margin and not enough gas.'),
  ('gaswell', 'intermediate', 'final', null, 37, 'Which sentence states the Professional tier''s claim?', '["A gas well loads when the velocity at its wellhead falls below the critical velocity computed under the correlation that same wellhead pressure selects.", "A gas well is a droplet balance, and the largest stable droplet at a critical Weber number sets the velocity every station has to beat.", "A gas well is a column of stations, the deepest one decides, and every remedy has to be argued there.", "A gas well is a rate, and the rate decides whether the liquid is carried."]'::jsonb, 2, 'The three functions a point check cannot reach are the profile, the sizing and the plunger, and each of them was worked at the controlling station.'),
  ('gaswell', 'intermediate', 'final', null, 38, '3.068 in reads 1.2865006128 at the EBOCHA-5 controlling station under Coleman, comfortably clear. Why will the sizing not return it?', '["Its ratio sits too far above one, and the objective is the candidate closest to the threshold from above, which is where the largest workable bore always lands.", "It fails under Turner, and the sizing scores both names before making a pick.", "It is not on the candidate list.", "It is smaller than something that also clears."]'::jsonb, 3, 'That is the whole objective, and 3.068 in is the candidate that survives a bad assumption at 1.0720838440 under Turner while 3.476 in falls to 0.8351796935.'),
  ('gaswell', 'intermediate', 'final', null, 39, 'On the published plunger case the engine returns 225.8581556122 psia and the independent oracle 225.9658011080 psia. Where does that difference live?', '["Almost entirely in the slug hydrostatic, at -0.1076108162 psi of the -0.1076454958 psi total.", "In the gas column, where the two evaluate the density at different pressures and the spread between those conventions is 2.1989080644 psi.", "In the plunger weight, which the oracle works in pascals and metres.", "In the friction term, which the oracle estimates and the engine leaves at zero."]'::jsonb, 0, 'The plunger weight terms agree to 0.0000e+0 psi and the gas column terms to 3.4680e-5 psi, so four of the five terms are not where the disagreement is.'),
  ('gaswell', 'intermediate', 'final', null, 40, 'Lowering the pressure at a station moves two things at once. Which two?', '["The interfacial tension and the liquid density fall, which is the lever a foamer pulls and the reason the two remedies are usually costed together.", "The flow area rises and the actual velocity falls with it.", "The gas density falls, which raises the critical velocity and lowers the critical rate together.", "The correlation switches at 1000.0 psia and the adjustment falls from 1.200000 to 1.000000."]'::jsonb, 2, 'Through 2.441 in at 540.0 degR the published water rows give 2496.154595078 Mscf/d at 2500.0 psia and 892.895047041 Mscf/d at 300.0 psia, so the bar comes down as the pressure does.'),
  ('gaswell', 'intermediate', 'final', null, 41, 'Sorting the given conditions into a traverse, a fluid and a plunger case is the first step of a professional reading. What does the sorting catch?', '["A pressure survey inconsistent with the rate, which the profile refuses rather than scoring, so the sorting turns a bare refusal into a readable error.", "A temperature in degF where the door wants degR, or a nominal tubing size standing in for an inside diameter.", "A correlation chosen at the wrong station, since the traverse labels every pressure it holds.", "A slug longer than its tubing, which the screen accepts without complaint."]'::jsonb, 1, 'The plunger case alone takes a depth, a diameter, a slug length and gravity, a plunger weight, a line pressure, a casing pressure and an average temperature, so sorting is where a unit in the wrong door shows up.'),
  ('gaswell', 'intermediate', 'final', null, 42, 'The 3.548 in row of the EBOCHA-5 sizing reads 0.9619521855 and so does the shoe station of its loading profile. Why is it the same number?', '["They are the same calculation: one diameter, one station, one rate.", "They are separate functions agreeing to ten digits, which the capstone carries as a check on the shared droplet constant of 1.5935346111.", "The sizing reads the ratio off the profile it was chained to, which is why the controlling point carries idIn 3.548.", "They differ, since the sizing scored it at the wellhead."]'::jsonb, 0, 'A sizing run at the controlling station therefore contains the loading verdict, and a rejection that matches the current string says the well is loading now.');
